# The Terraform variables of prod, from cervinschi-infra → /trivia-more/prod and the shared folders; sourced by infra/run.sh.
export TF_VAR_console_infisical_client_id="${CONSOLE_INFISICAL_CLIENT_ID:?add it to cervinschi-infra → /trivia-more/prod}"
export TF_VAR_console_infisical_client_secret="${CONSOLE_INFISICAL_CLIENT_SECRET:?add it to cervinschi-infra → /trivia-more/prod}"
export TF_VAR_infisical_project_id="${INFISICAL_PROJECT_ID:?add INFISICAL_PROJECT_ID to cervinschi-infra → /trivia-more/terraform}"
export TF_VAR_infisical_site_url="${INFISICAL_SITE_URL:?add INFISICAL_SITE_URL to cervinschi-infra → /trivia-more/terraform}"
export TF_VAR_console_seq_api_key="${CONSOLE_SEQ_API_KEY:?add CONSOLE_SEQ_API_KEY to cervinschi-infra → /trivia-more/prod}"
export TF_VAR_console_worker_seq_api_key="${CONSOLE_WORKER_SEQ_API_KEY:?add CONSOLE_WORKER_SEQ_API_KEY to cervinschi-infra → /trivia-more/prod}"
export TF_VAR_server_ip="${SAVVY_PUBLIC_IP:?add SAVVY_PUBLIC_IP to cervinschi-infra → /trivia-more/prod}"
export TF_VAR_console_owner_email="${CONSOLE_OWNER_EMAIL:?add CONSOLE_OWNER_EMAIL to cervinschi-infra → /cloudflare}"
export INFISICAL_HOST="${TF_INFISICAL_HOST:?add TF_INFISICAL_HOST to cervinschi-infra → /trivia-more/terraform}"
export INFISICAL_UNIVERSAL_AUTH_CLIENT_ID="${TF_INFISICAL_CLIENT_ID:?add TF_INFISICAL_CLIENT_ID to cervinschi-infra → /trivia-more/terraform}"
export INFISICAL_UNIVERSAL_AUTH_CLIENT_SECRET="${TF_INFISICAL_CLIENT_SECRET:?add TF_INFISICAL_CLIENT_SECRET to cervinschi-infra → /trivia-more/terraform}"
export TF_VAR_postgres_password="${PROD_POSTGRES_PASSWORD:?add PROD_POSTGRES_PASSWORD to cervinschi-infra → /trivia-more/prod}"
export TF_VAR_savvy_tailnet_host="${SAVVY_TAILNET_HOST:?add SAVVY_TAILNET_HOST to cervinschi-infra → /trivia-more/prod}"
